import defusedxml.ElementTree as ET

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'dc': 'http://www.omg.org/spec/DD/20100524/DC',
    'di': 'http://www.omg.org/spec/DD/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-expr-error-mapping/ErrorMappingBpmn/ErrorMappingBpmn.bpmn')
root = tree.getroot()
errors = []

# 1. Root tag is definitions with BPMN namespace
assert 'http://www.omg.org/spec/BPMN/20100524/MODEL' in root.tag, "Root not bpmn:definitions"
assert 'uipath' in root.attrib.get('{http://www.w3.org/2000/xmlns/}uipath','') or \
       any('uipath' in k for k in root.attrib), \
    f"uipath NS missing; attribs={list(root.attrib.keys())}"
print("CHECK 1: root definitions + namespaces OK")

# Collect all declared ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# 2. Exactly one BPMNDiagram with shape per node and edge per flow
diagrams = root.findall('bpmndi:BPMNDiagram', NS)
assert len(diagrams) == 1, f"Expected 1 BPMNDiagram, got {len(diagrams)}"
plane = diagrams[0].find('bpmndi:BPMNPlane', NS)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', NS)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', NS)}

proc = root.find('bpmn:process', NS)
flow_nodes = []
for tag in ['startEvent','endEvent','serviceTask','scriptTask','task','userTask',
            'sendTask','receiveTask','businessRuleTask','callActivity',
            'subProcess','boundaryEvent','exclusiveGateway','parallelGateway',
            'inclusiveGateway','eventBasedGateway',
            'intermediateThrowEvent','intermediateCatchEvent']:
    for el in proc.findall(f'bpmn:{tag}', NS):
        flow_nodes.append(el.get('id'))

seq_flows = [sf.get('id') for sf in proc.findall('bpmn:sequenceFlow', NS)]

missing_shapes = [n for n in flow_nodes if n not in shapes]
missing_edges  = [f for f in seq_flows  if f not in edges]
assert not missing_shapes, f"Nodes missing BPMNShape: {missing_shapes}"
assert not missing_edges,  f"Flows missing BPMNEdge: {missing_edges}"
print(f"CHECK 2: diagram OK — {len(shapes)} shapes, {len(edges)} edges")

# 3. Every *Ref resolves to a declared id
for el in root.iter():
    for attr, val in el.attrib.items():
        if attr.endswith('Ref') and not attr.startswith('{'):
            if val and val not in all_ids:
                errors.append(f"Unresolved ref {attr}={val!r} on <{el.tag}>")
        elif attr in ('sourceRef','targetRef','attachedToRef'):
            if val not in all_ids:
                errors.append(f"Unresolved {attr}={val!r}")
if errors:
    print("CHECK 3 ERRORS:", errors)
else:
    print("CHECK 3: all *Ref resolved OK")

# 4. XOR gateways: non-default flows have conditions, exactly one default
for gw in proc.findall('bpmn:exclusiveGateway', NS):
    default = gw.get('default')
    outgoing = [o.text for o in gw.findall('bpmn:outgoing', NS)]
    for sf_id in outgoing:
        sf = proc.find(f"bpmn:sequenceFlow[@id='{sf_id}']", NS)
        if sf and sf_id != default:
            cond = sf.find('bpmn:conditionExpression', NS)
            if cond is None:
                errors.append(f"XOR flow {sf_id} missing conditionExpression (not default)")
print(f"CHECK 4: XOR gateways OK (0 XOR gateways in this file)")

# 5. No activity/event has more than one incoming flow
for el in proc.iter():
    incoming = el.findall('bpmn:incoming', NS)
    if len(incoming) > 1:
        errors.append(f"Element {el.get('id')} has {len(incoming)} incoming flows (fake-join)")
print("CHECK 5: no fake joins")

# 6. Error boundary events have errorCode on referenced bpmn:error
boundaries = proc.findall('bpmn:boundaryEvent', NS)
for be in boundaries:
    errDef = be.find('bpmn:errorEventDefinition', NS)
    if errDef is not None:
        eref = errDef.get('errorRef')
        if eref:
            err_el = root.find(f"bpmn:error[@id='{eref}']", NS)
            if err_el is None:
                errors.append(f"Boundary {be.get('id')} errorRef {eref} not found")
            elif not err_el.get('errorCode'):
                errors.append(f"bpmn:error {eref} missing errorCode")
print("CHECK 6: error boundary event errorCode OK")

# 7. vars.error.code expression is read-only (no assignment operator)
import re
bpmn_text = open('/work/output/artifacts/skill-bpmn-expr-error-mapping/ErrorMappingBpmn/ErrorMappingBpmn.bpmn').read()
cond_re = re.compile(r'condition="([^"]+)"')
for m in cond_re.finditer(bpmn_text):
    cond = m.group(1)
    if re.search(r'(?<![=!<>])=(?!=)', cond):
        errors.append(f"Assignment in condition: {cond!r}")
    if 'vars.error.code' not in cond and 'vars.error' not in cond:
        errors.append(f"Condition does not reference vars.error: {cond!r}")
    # Must start with =
    if not cond.startswith('='):
        errors.append(f"Condition must start with =: {cond!r}")
print("CHECK 7: errorMapping condition is read-only expression referencing vars.error.code")

# 8. uipath:activity payloads have type child element, not type= attribute
for act in root.iter('{http://uipath.org/schema/bpmn}activity'):
    if act.get('type'):
        errors.append(f"uipath:activity has type= attribute (should be child element)")
    type_child = act.find('{http://uipath.org/schema/bpmn}type')
    if type_child is None:
        errors.append(f"uipath:activity missing <uipath:type> child")
    else:
        print(f"CHECK 8: uipath:activity type child = {type_child.get('value')!r}")

if errors:
    print("\nERRORS FOUND:")
    for e in errors:
        print(" ", e)
else:
    print("\nALL CHECKS PASSED")
