missing_shapes = [n for n in flow_nodes if n not in shapes]
missing_edges  = [f for f in seq_flows  if f not in edges]
assert not missing_shapes, f"Nodes missing BPMNShape: {missing_shapes}"
assert not missing_edges,  f"Flows missing BPMNEdge: {missing_edges}"
print(f"CHECK 2: diagram OK — {len(shapes)} shapes ({flow_nodes}), {len(edges)} edges")

# 3. Every *Ref resolves to a declared id
for el in root.iter():
    for attr in list(el.attrib):
        local = attr.split('}')[-1]
        val = el.get(attr,'')
        if local.endswith('Ref') and val and val not in all_ids:
            errors.append(f"Unresolved {local}={val!r} on <{el.tag}>")
